"""
AgentResponseGenerated Domain Event.
"""

from __future__ import annotations

from dataclasses import dataclass

from shared.kernel.domain_event import DomainEvent


@dataclass(frozen=True)
class AgentResponseGenerated(DomainEvent):
    """Domain Event published when agent text response is generated by LLM runtime."""

    session_id: str = ""
    turn_id: str = ""
    response_text: str = ""
